// ============================================================
// Parse RSS v14
// v13: detectRealtimeSource() toLowerCase() 추가, 빈 XML early continue
// v14: FinancialJuice 패스스루 로직 추가
//      detectSource()에 financialjuice.com 추가
//      패스스루 항목 normalizeLink() 적용 (Codex)
//      PASSTHROUGH_SOURCES Set 방식 (Codex + ChatGPT 권장)
// ============================================================
const items = $input.all();
const results = [];
const seenLinks = new Set();

// v14: 패스스루 소스 명시 (우발적 패스스루 방지)
// 추후 소스 추가 시 여기만 수정
const PASSTHROUGH_SOURCES = new Set(['FinancialJuice']);

const NOISE_KEYWORDS = [
  'price prediction', 'best crypto', 'buy now', 'top coins',
  'advertorial', 'sponsored', 'beginners guide', 'is it worth', 'pros and cons',
  'how to', 'how much', 'should you', 'retire',
  'long term', 'technical analysis', 'trading strategy', 'market outlook',
  'year forecast', 'price target for', 'what is ', 'explained', ' vs ',
  'live updates', 'live blog', 'roundup', 'opinion', 'commentary'
];

function detectSource(link) {
  const l = link.toLowerCase();
  if (l.includes('benzinga.com'))       return 'Benzinga';
  if (l.includes('cnbc.com'))           return 'CNBC';
  if (l.includes('marketwatch.com'))    return 'MarketWatch';
  if (l.includes('nytimes.com'))        return 'NYT';
  if (l.includes('yahoo.com'))          return 'Yahoo Finance';
  if (l.includes('bloomberg.com'))      return 'Bloomberg';
  if (l.includes('seekingalpha.com'))   return 'Seeking Alpha';
  if (l.includes('financialjuice.com')) return 'FinancialJuice'; // v14 추가
  return 'Unknown';
}

function detectRealtimeSource(xml) {
  const x = (xml || '').toLowerCase();
  if (x.includes('dowjones.io') || x.includes('mw_realtimeheadlines')) return 'MarketWatch Realtime';
  return null;
}

function extractText(block, keys) {
  for (const key of keys) {
    const regex = new RegExp(`<${key}[^>]*>\\s*<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>\\s*<\\/${key}>`, 'i');
    const cdataMatch = block.match(regex);
    if (cdataMatch) return cdataMatch[1].trim();
    const regex2 = new RegExp(`<${key}[^>]*>([\\s\\S]*?)<\\/${key}>`, 'i');
    const match = block.match(regex2);
    if (match) return match[1].trim();
  }
  return '';
}

function normalizeLink(url) {
  return url.trim().replace(/#.*$/, '').split('?')[0].replace(/\/+$/, '');
}

function extractLink(block) {
  const alt = block.match(/<link\b(?=[^>]*\brel=["']alternate["'])(?=[^>]*\bhref=["']([^"']+)["'])[^>]*>/i);
  if (alt) return normalizeLink(alt[1]);

  const href = block.match(/<link[^>]+href=["']([^"']+)["']/i);
  if (href) return normalizeLink(href[1]);

  const text = block.match(/<link>([^<]+)<\/link>/i);
  if (text) return normalizeLink(text[1]);

  const guid = block.match(/<guid[^>]*>([^<]+)<\/guid>/i);
  if (guid && guid[1].startsWith('http')) return normalizeLink(guid[1]);

  return '';
}

function decode(str) {
  return str
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&#x2019;/g, "'")
    .replace(/&#x2018;/g, "'")
    .replace(/&#x201C;/g, '"')
    .replace(/&#x201D;/g, '"')
    .replace(/&#8230;/g, '...')
    .replace(/&#8216;/g, "'")
    .replace(/&#8217;/g, "'")
    .replace(/<[^>]+>/g, '')
    .trim();
}

const nowMs = Date.now();

for (const item of items) {

  // ✅ v14: 이미 정규화된 항목 패스스루 (FinancialJuice Code 노드 출력)
  if (PASSTHROUGH_SOURCES.has(item.json.source) && item.json.title && item.json.link) {
    const link = normalizeLink(item.json.link || '');
    if (link && !seenLinks.has(link)) {
      seenLinks.add(link);
      results.push({ json: { ...item.json, link } });
    }
    continue;
  }

  // 기존 XML 소스 (8개) 처리
  const xml = (item.json.data || item.json.body || '').trim();
  if (!xml) continue;

  const realtimeSource = detectRealtimeSource(xml);

  const blocks = [
    ...(xml.match(/<item[\s\S]*?<\/item>/gi) || []),
    ...(xml.match(/<entry[\s\S]*?<\/entry>/gi) || [])
  ];

  for (const block of blocks) {
    const title   = decode(extractText(block, ['title']));
    const link    = extractLink(block);
    const desc    = decode(extractText(block, ['content:encoded', 'description', 'summary'])).substring(0, 1000);
    const pubDate = extractText(block, ['pubDate', 'updated', 'published']).trim();

    if (!title || !link) continue;
    if (seenLinks.has(link)) continue;

    const text = (title + ' ' + desc).toLowerCase();
    if (NOISE_KEYWORDS.some(k => text.includes(k))) continue;

    if (!pubDate) continue;
    const pub = new Date(pubDate);
    if (isNaN(pub.getTime())) continue;

    const age_minutes_raw = (nowMs - pub.getTime()) / 60000;
    if (age_minutes_raw > 1440) continue;
    if (age_minutes_raw < -60)  continue;

    seenLinks.add(link);

    let domain = '';
    try { domain = new URL(link).hostname; } catch {}

    const source      = realtimeSource || detectSource(link);
    const age_minutes = Math.round(age_minutes_raw);

    results.push({
      json: {
        source,
        title,
        link,
        domain,
        contentSnippet: desc,
        pubDate,
        age_minutes,
      }
    });
  }
}

return results;

// ============================================================
// Keyword Filter (Company AND Event) — v23  BEST
// n8n Code 노드에 그대로 붙여넣기 가능
//
// 통과 경로 요약 (우선순위 순):
//   1. 지정학/거시 충격  → isGeopolitical
//   2. 매크로 이벤트    → (hasMacroKeyword || hasMacroAction)
//                          AND (isMacroSource || hasMacroEntity)
//                          AND !isMacroNoise
//   3. 기업 이벤트      → hasCompany AND (hasEvent || chipShock)
//      ※ 2·3 경로 이전에 Reaction 기사 차단
//
// 수정 이력:
//   v10–v19: 기업 이벤트 필터 정교화 (Reaction 차단, 티커 보강 등)
//   v20: FinancialJuice 매크로 소스 통합
//         · MACRO_KEYWORDS, MACRO_ENTITIES_RE 신설
//         · source_type === 'macro' 전용 로직
//   v21: 버그 3개 수정 + Codex 제안 반영
//         · minLen: 40 → isMacroSource ? 10 : 40
//         · MACRO 통과 조건: (isMacroSource || hasMacroEntity) 추가
//         · MACRO_NOISE_PATTERNS 신설 (소비자금융 해설 차단)
//   v22: Codex 보정 3개
//         · minLen: (isMacroSource || hasMacroEntity) ? 10 : 40
//         · u\.s\. treasury → u\.?s\.? (US Treasury 점 없는 형태 커버)
//         · MACRO_ACTION_RE 신설 (entity + 동사 조합 보조 경로)
//   v23: Codex 오탐 방지 보정 4개
//         · MACRO_ACTION_RE 동사 축소 (says/announces/expects 제거)
//         · MACRO_CONTEXT_RE 신설 → entity + 동사 + 경제 문맥 3중 게이트
//         · MACRO_ENTITIES_RE에서 white house / pentagon 제거
//         · MACRO_KEYWORDS에 'signals cut' 패턴 추가
// ============================================================

const items     = $input.all();
const seenLinks = new Set();
const results   = [];

// ── 유틸
const escapeRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// ════════════════════════════════════════════════════════════
//  섹션 1: 기업 식별 (Company / Ticker)
// ════════════════════════════════════════════════════════════

const COMPANY_NAMES = [
  'nvidia', 'amd', 'intel', 'tsmc', 'qualcomm', 'broadcom',
  'arm holdings', 'arm ltd',
  'samsung', 'sk hynix', 'micron', 'asml', 'smci', 'marvell',
  'apple', 'microsoft', 'google', 'alphabet', 'meta', 'amazon', 'tesla',
  'lockheed', 'raytheon', 'northrop', 'boeing', 'palantir',
  'exxon', 'chevron', 'goldman sachs', 'morgan stanley', 'jpmorgan',
];
const COMPANY_NAME_RES = COMPANY_NAMES.map(
  n => new RegExp('(^|[^a-z0-9-])' + escapeRe(n) + '(?=$|[^a-z0-9-])', 'i')
);

// 긴 티커 — 오탐 위험 낮음
const TICKERS = [
  'nvda','intc','tsm','qcom','avgo',
  'asml','smci','klac','lrcx','amat',
  'aapl','msft','googl','amzn','tsla',
  'lmt','rtx','noc','pltr','xom','cvx','jpm',
];
const TICKER_RE = new RegExp(
  '(^|[^a-z0-9.-])(?:' + TICKERS.map(escapeRe).join('|') + ')(?=$|[^a-z0-9.-])', 'i'
);

// 짧은 티커 — title + 재무 맥락 AND 조건 필수 (MS Office, ARM Yourself 오탐 방지)
const SHORT_TICKER_TITLE_RE   = /(^|[\s(\[])(MU|BA|MS|GS|ARM|META)(?=[:)\]\s]|$)/;
const SHORT_TICKER_CONTEXT_RE = /\b(earnings?|guidance|results?|eps|revenue|beat(?:s|en)?|miss(?:es|ed)?|upgrades?|downgrades?|initiates?|coverage|target|cut|raises?|wins?|contract|deal|files?|sec|8-k)\b/i;

function hasCompanyMatch(text, rawTitle) {
  const shortHit =
    SHORT_TICKER_TITLE_RE.test(rawTitle) &&
    SHORT_TICKER_CONTEXT_RE.test(rawTitle.toLowerCase());
  return COMPANY_NAME_RES.some(re => re.test(text)) ||
         TICKER_RE.test(text) ||
         shortHit;
}

// ════════════════════════════════════════════════════════════
//  섹션 2: 매크로 이벤트 감지
// ════════════════════════════════════════════════════════════

// 중앙은행 / 국제기구 엔티티 (white house·pentagon 제거 — 정치 오탐 방지)
const MACRO_ENTITIES_RE = /\b(fed|federal reserve|ecb|european central bank|boj|bank of japan|boe|bank of england|pboc|rba|rbnz|fomc|powell|lagarde|ueda|yellen|opec|imf|world bank|u\.?s\.? treasury)\b/i;

// 보조 액션 동사 (좁게 유지 — says/announces/expects 제거로 정치 기사 오탐 방지)
const MACRO_ACTION_RE   = /\b(raises?|cuts?|holds?|hikes?|signals?|warns?)\b/i;

// 경제 문맥 게이트 (entity + 동사만으로 통과 방지)
// "Lagarde warns of political uncertainty" → warns 있어도 경제 문맥 없으면 차단
const MACRO_CONTEXT_RE  = /\b(rate|rates|bps|inflation|cpi|pce|payroll|nfp|unemployment|gdp|pmi|yield|treasury|oil|crude|opec|tariff|sanction)\b/i;

// 소비자금융 해설 기사 차단
// "Fed raises rates — here's why your mortgage costs more" → isMacroNoise = true
const MACRO_NOISE_PATTERNS = [
  'mortgage', 'savings account', 'what to do', 'how to',
  'personal finance', 'your portfolio', 'your savings', 'your mortgage',
  'what it means for you', "here's why", 'here is why', 'this is why',
  'explainer', 'everything you need', 'what investors should',
];

// 매크로 이벤트 키워드 (hasCompany 불필요)
const MACRO_KEYWORDS = [
  // 금리 액션
  'raises rates', 'rate hike',   'rate cut',        'rate cuts',
  'signals cut',  'signals rate cut', 'rate cut signal',
  'holds rates',  'rate hold',   'rates unchanged',
  'interest rate decision',      'rate decision',
  'hikes rates',  'cuts rates',  'basis points',    'bps',
  // 중앙은행 발화 (콜론 포함 — FinancialJuice 헤드라인 패턴)
  'powell:', 'lagarde:', 'ueda:', 'yellen:',
  'fed chair', 'ecb president', 'boj governor',
  // 경제지표
  'cpi ',    'core cpi',     'pce ',          'core pce',
  'nonfarm payroll',         'nfp ',          'jobs report',
  'unemployment rate',       'jobless claims',
  'gdp growth', 'gdp contracts', 'gdp shrinks',
  'retail sales', 'pmi ',   'inflation data', 'inflation report',
  // OPEC / 에너지
  'opec cuts',  'opec raises', 'opec holds',
  'opec+ cuts', 'opec+ raises',
  'output cut', 'production cut', 'supply cut',
  // 관세 / 무역
  'imposes tariffs', 'new tariffs', 'tariff hike',
  'trade war escalates', 'trade deal',
  // 시장 지수 충격
  'dow falls',    'dow rises',    'dow tumbles',
  's&p falls',    's&p rises',    's&p tumbles',
  'nasdaq falls', 'nasdaq rises', 'nasdaq tumbles',
  // 채권 / 달러
  'yield spikes', 'yield surges', 'yield rises',
  '10-year yield', '2-year yield', 'treasury yield',
  'dollar surges', 'dollar plunges', 'dollar index',
  // 지정학 속보 (GEOPOLITICAL 안전망)
  'nuclear', 'ceasefire', 'peace deal', 'invades', 'invasion',
];

// ════════════════════════════════════════════════════════════
//  섹션 3: 기업 이벤트 키워드
// ════════════════════════════════════════════════════════════

const EVENT_KEYWORDS = [
  // 실적 / 가이던스
  'earnings',         'guidance',         'forecast',
  '8-k',              'sec filing',       'files 8-k',
  'beat estimates',   'miss estimates',   'beats',    'misses',  ' beat',
  'revenue beat',     'revenue miss',
  'quarterly revenue','annual revenue',
  'quarterly profit', 'quarterly loss',   'net loss', 'net profit',
  'reports q',        'quarterly results',
  'announces results','announces earnings',
  // M&A / 규제
  'merger', 'acquisition', 'm&a',
  'export restriction', 'lawsuit', 'regulation',
  // 애널리스트 액션
  'analyst upgrade', 'analyst downgrade',
  'upgrades', 'downgrades',
  'initiates coverage', 'initiates at', 'coverage initiation',
  'target raised', 'target cut',
  'raises guidance', 'raises forecast', 'raises outlook',
  'cuts guidance',   'cuts forecast',   'cuts outlook',
  // 시장 충격
  'selloff', 'sell-off',
  // 기술 / 산업
  'chip shortage', 'chip export',
  'data center revenue', 'data center deal',
  'semiconductor export',
  'ai chip', 'ai investment',
  // CEO / CFO
  'ceo resigns', 'ceo fired', 'ceo steps down',
  'cfo resigns', 'cfo fired', 'cfo steps down',
  'appoints ceo', 'appoints cfo', 'new ceo', 'new cfo',
  // 방산 / 정부 계약 (복합만 — 단독 contract/award 오탐 방지)
  'wins contract',      'win contract',
  'awarded contract',   'defense contract',   'government contract',
  'pentagon contract',  'military contract',
  'defense deal',       'government deal',    'awarded $',
];

// NYT — 지정학/거시 위주라 재무 이벤트 키워드 축소
const NYT_EVENT_KEYWORDS = [
  'earnings', 'guidance', 'merger', 'acquisition', 'm&a',
  'export restriction', 'sanctions', 'sec filing', '8-k',
  'beat estimates', 'miss estimates', 'target raised', 'target cut',
  'reports q', 'quarterly results', 'announces earnings',
  'iran', 'airstrike', 'military strike', 'oil supply',
];

// ════════════════════════════════════════════════════════════
//  섹션 4: 지정학 / 거시 충격
// ════════════════════════════════════════════════════════════

const GEOPOLITICAL_KEYWORDS = [
  'airstrike',       'air strike',
  'military strike', 'missile strike',
  'strait of hormuz','hormuz',
  'war in iran',     'war in middle east', 'conflict in middle east',
  'export ban',
  'dow dives',   'dow plunges',   'dow drops',   'dow slides',
  'market crash','market plunge', 'market selloff','selloff accelerates',
  'stocks plunge','stocks tumble','stocks slide',
  'oil spikes',  'oil surges',
  'circuit breaker','black monday','flash crash',
  'chip ban',         'chip export ban',        'semiconductor export ban',
  'chip restriction', 'semiconductor restriction',
];

// ════════════════════════════════════════════════════════════
//  섹션 5: 노이즈 차단
// ════════════════════════════════════════════════════════════

// Reaction 기사 (price 반응 해설 — 이벤트 기사 아님)
const REACTION_PATTERNS = [
  // stock
  'stock surges','stock surge','stock surged',
  'stock jumps', 'stock jump', 'stock jumped',
  'stock soars', 'stock soar', 'stock soared',
  'stock climbs','stock climb','stock climbed',
  'stock rallies','stock rally','stock rallied',
  'stock falls', 'stock fall', 'stock fell',
  'stock drops', 'stock drop', 'stock dropped',
  'stock plunges','stock plunge','stock plunged',
  'stock tumbles','stock tumble','stock tumbled',
  'stock slides','stock slide','stock slid',
  'stock dives', 'stock dive', 'stock dived',
  'stock gains after','stock rises after','stock rose',
  // shares
  'shares surge','shares surges','shares surged',
  'shares jump', 'shares jumps', 'shares jumped',
  'shares soar', 'shares soars', 'shares soared',
  'shares climb','shares climbs','shares climbed',
  'shares rally','shares rallies','shares rallied',
  'shares fall', 'shares falls', 'shares fell',
  'shares drop', 'shares drops', 'shares dropped',
  'shares plunge','shares plunges','shares plunged',
  'shares tumble','shares tumbles','shares tumbled',
  'shares slide','shares slides','shares slid',
  'shares gain after','shares rise after','shares rose',
  // stocks 복수
  'stocks surge','stocks surged','stocks jump','stocks jumped',
  'stocks soar', 'stocks soared','stocks fall', 'stocks fell',
  'stocks drop', 'stocks dropped','stocks plunge','stocks plunged',
  'stocks tumble','stocks tumbled','stocks slide','stocks slid',
  'stocks rally','stocks rallied',
  // after/following (결과 해설)
  'after earnings','after results','after reporting',
  'after beating', 'after missing','after the report',
  'following earnings','following results',
];
// stock up/down — 'stock update', 'stock upside' 오탐 방지
const REACTION_REGEXES = [
  /\b(stock|shares|stocks)\s+(up|down|higher|lower)\b/i,
];

// 크립토 노이즈 — 회사명 없으면 차단
const CRYPTO_NOISE = [
  'bitcoin price prediction','crypto price prediction',
  'will bitcoin','btc price target','ethereum price target',
];

// outlook 맥락 기반 허용 (Microsoft Outlook 제품명 오탐 방지)
const OUTLOOK_RE     = /\boutlook\b/i;
const OUTLOOK_CTX_RE = /\b(raises?|cuts?|guidance|forecast|revenue|eps|profit|q[1-4]|fy\d{2,4}|full[- ]year)\b/i;

// ════════════════════════════════════════════════════════════
//  메인 루프
// ════════════════════════════════════════════════════════════

for (const item of items) {
  if (item.json._empty)  continue;
  if (!item.json.link)   continue;

  const link = item.json.link.split('?')[0];
  if (seenLinks.has(link)) continue;

  // isMacroSource: 최상단에서 계산 (minLen 결정에 필요)
  const isMacroSource = item.json.source_type === 'macro';

  const rawTitle = (item.json.title || '').trim();
  const title    = rawTitle.toLowerCase();
  const text     = (title + ' ' + (item.json.contentSnippet || item.json.content || '')).toLowerCase();

  // ── 최소 길이 게이트
  // macro 소스 또는 매크로 엔티티 명시 시 10자 (예: "ECB HOLDS RATES" 15자 대응)
  // 일반 소스는 40자 (단문 노이즈 차단)
  const hasMacroEntity = MACRO_ENTITIES_RE.test(text);
  const minLen = (isMacroSource || hasMacroEntity) ? 10 : 40;
  if (text.length < minLen) continue;

  // ── "Why ..." 제목 차단 (reaction explanation)
  if (title.trimStart().startsWith('why ')) continue;

  const hasCompany = hasCompanyMatch(text, rawTitle);

  // ── 크립토 노이즈 차단
  if (CRYPTO_NOISE.some(k => text.includes(k)) && !hasCompany) continue;

  // ──────────────────────────────────────────────────────────
  //  경로 1: 지정학 / 거시 충격
  //  hasCompany 불필요, Reaction 필터 면제
  // ──────────────────────────────────────────────────────────
  const hasIran        = text.includes('iran');
  const hasOil         = text.includes('oil') || text.includes('crude');
  const hasMarketShock = ['selloff','tumble','plunge','attack','strike','sanction'].some(k => text.includes(k));
  const hasTariff      = text.includes('tariff');

  const isGeopolitical =
    (hasIran && (hasOil || hasMarketShock))             ||
    (hasTariff && (hasMarketShock || text.includes('stock') || text.includes('market'))) ||
    text.includes('sanctions on')                       ||
    text.includes('oil supply')                         ||
    text.includes('crude oil')                          ||
    GEOPOLITICAL_KEYWORDS.some(k => text.includes(k));

  if (isGeopolitical) {
    seenLinks.add(link);
    results.push({ ...item, json: { ...item.json } });
    continue;
  }

  // ──────────────────────────────────────────────────────────
  //  경로 2: 매크로 이벤트
  //  조건: (hasMacroKeyword || hasMacroAction)
  //        AND (isMacroSource || hasMacroEntity)
  //        AND !isMacroNoise
  //
  //  hasMacroAction = entity + 동사 + 경제 문맥 (3중 게이트)
  //  예시:
  //    FJ "ECB HOLDS RATES"        → isMacroSource + hasMacroKeyword → 통과
  //    BZ "Powell signals cut"     → hasMacroEntity + signals cut KW → 통과
