  //    BZ "Lagarde warns politics" → warns 있지만 CONTEXT 없음 → 차단
  //    BZ "White House says tariffs" → white house 제거됨 → entity 없음 → 차단
  // ──────────────────────────────────────────────────────────
  const hasMacroKeyword = MACRO_KEYWORDS.some(k => text.includes(k));
  const isMacroNoise    = MACRO_NOISE_PATTERNS.some(k => text.includes(k));
  const hasMacroAction  = hasMacroEntity &&
                          MACRO_ACTION_RE.test(text) &&
                          MACRO_CONTEXT_RE.test(text);

  if ((hasMacroKeyword || hasMacroAction) && (isMacroSource || hasMacroEntity) && !isMacroNoise) {
    seenLinks.add(link);
    results.push({ ...item, json: { ...item.json } });
    continue;
  }

  // ──────────────────────────────────────────────────────────
  //  Reaction 차단 (경로 1·2 이후 실행)
  //  매크로 소스는 면제 (RAISES/CUTS 자체가 이벤트이므로)
  // ──────────────────────────────────────────────────────────
  if (!isMacroSource) {
    const isReaction =
      REACTION_PATTERNS.some(k => text.includes(k)) ||
      REACTION_REGEXES.some(re => re.test(text));
    if (isReaction) continue;
  }

  // ──────────────────────────────────────────────────────────
  //  경로 3: 기업 이벤트
  //  조건: hasCompany AND (hasEvent || chipShock)
  // ──────────────────────────────────────────────────────────
  const chipShock =
    (text.includes('chip') || text.includes('semiconductor')) &&
    (text.includes('shortage') || text.includes('sanction'));

  const keywords        = item.json.source === 'NYT' ? NYT_EVENT_KEYWORDS : EVENT_KEYWORDS;
  const hasEventBase    = keywords.some(k => text.includes(k));
  const hasFinancialOutlook = OUTLOOK_RE.test(text) && OUTLOOK_CTX_RE.test(text);
  const hasEvent        = hasEventBase || hasFinancialOutlook;

  if (!(hasCompany && (hasEvent || chipShock))) continue;

  seenLinks.add(link);
  results.push({ ...item, json: { ...item.json } });
}

