// Parse GPT + Route Decision
// v1: 기본 파싱 + route 결정
// v2: 한글 가드 + direction 정규화 (Fix 1)
// v3: direction_fixed 대소문자 오탐 수정
//     ticker sanitize / event_id 결정적 키 / thesis 140자 / parse error 로그
// v4: MULTI 차단 해제 / UNKNOWN만 discard / is_multi·has_valid_ticker 플래그 / Macro 추가
// v5: ticker 하이픈 → 점 변환 / event_type 정규화 함수 추가
// v6: [Codex P2-1] normalizeEventType 부분 매칭 강화 (변형 변수 커버)
//     [Codex P2-2] shock_score/confidence 파싱 강화 ("4/5", "4점" 형태 처리)
// v7: [ChatGPT] parseScore 소수 문자열 처리 강화 ("4.5"→5, "0.8"→1)
// v8: thesis 접두어 후처리 ("한국어 한 문장:", "요약:" 등 gpt-4o-mini 오출력 제거)
// v9: Analyst 이벤트 조건부 추가 (빅테크/반도체 whitelist + score3 + confidence>=3만 Free 허용)
// ============================================================

const item = $input.first().json;

// ── 1. GPT 응답 파싱 ───────────────────────────────────────
let parsed;
const raw = item.message?.content;

if (raw && typeof raw === 'object') {
  parsed = raw;
} else {
  try {
    const clean = (raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
    parsed = JSON.parse(clean);
  } catch(e) {
    console.log('[GPT_PARSE_ERROR]', String(raw).substring(0, 200));
    return [{ json: { action: 'SKIP', shock_score: 0, confidence: 0, _route: 'discard', _parse_error: true } }];
  }
}

if (parsed.shock_score === undefined || !parsed.event_type) {
  return [{ json: { action: 'SKIP', shock_score: 0, confidence: 0, _route: 'discard', _invalid: true } }];
}

// ── 2. 한글 가드 ───────────────────────────────────────────
// ✅ v8: thesis 접두어 후처리
// gpt-4o-mini가 "한국어 한 문장: ...", "요약: ..." 형태로 뱉는 경우 제거
const thesis = String(parsed.thesis || parsed['1line_thesis'] || '')
  .trim()
  .replace(/^(한국어\s*한\s*문장|한\s*문장\s*요약|한줄\s*요약|요약)\s*[:：]\s*/i, '')
  .trim()
  .slice(0, 140);

if (!/[가-힣]/.test(thesis)) {
  console.log(`[KO_GUARD] 영어 thesis 감지 → SKIP: ${thesis.substring(0, 80)}`);
  return [{ json: {
    action: 'SKIP',
    _route: 'discard',
    _non_korean_thesis: true,
    shock_score: 0,
    confidence: 0
  }}];
}

// ── 3. Direction 정규화 ────────────────────────────────────
function normalizeDirection(value) {
  if (value === undefined || value === null) return 'Neutral';
  const s = String(value).trim().toLowerCase();
  if (!s || ['none', 'null', 'undefined', 'n/a', 'na', 'unknown'].includes(s)) return 'Neutral';
  if (['bullish', 'bull', 'positive', 'up', 'long', 'buy', 'upside'].includes(s)) return 'Bullish';
  if (['bearish', 'bear', 'negative', 'down', 'short', 'sell', 'downside'].includes(s)) return 'Bearish';
  if (['neutral', 'flat', 'mixed', 'unclear'].includes(s)) return 'Neutral';
  return 'Neutral';
}

