// ✅ v6: 부분 매칭(includes) 추가로 변형 변수 커버
// "supply chain", "supply-chain", "macro event", "regulatory" 등 모두 처리
function normalizeEventType(v) {
  const s = String(v || '').trim().toLowerCase();

  if (s.includes('earning'))                             return 'Earnings';
  if (s.includes('guidance'))                            return 'Guidance';
  if (s.includes('regulat'))                             return 'Regulation';  // regulation, regulatory
