  if (value === undefined || value === null) return 0;

  // 이미 숫자면 반올림 후 반환
  if (typeof value === 'number') return Math.min(5, Math.max(0, Math.round(value)));

  const s = String(value).trim();

  // "4/5", "4.5/5" 형태 — 분자만 추출 후 반올림
  const slashMatch = s.match(/^(\d+(?:\.\d+)?)\s*\/\s*\d+(?:\.\d+)?$/);
  if (slashMatch) return Math.min(5, Math.max(0, Math.round(parseFloat(slashMatch[1]))));

  // "4점", "4.5점", "score: 4", "4 out of 5" 등 — 첫 번째 수(소수 포함) 추출
  const floatMatch = s.match(/\d+(?:\.\d+)?/);
  if (floatMatch) return Math.min(5, Math.max(0, Math.round(parseFloat(floatMatch[0]))));

  return 0;
}

