// ============================================================
// FinancialJuice Normalize v4
// v1: stripHtml, split('?')[0], age_minutes 계산
// v2: domain 안전, pubDate fallback 확장, source_type 추가
// v3: normalizeLink() 추가, age_minutes 범위 필터
// v4: pubDate 없는 항목 제거 (Parse RSS 완전 일치)
// ============================================================
const now = Date.now();

const stripHtml = (s = '') =>
  s.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

const normalizeLink = (url = '') =>
  url.trim().replace(/#.*$/, '').split('?')[0].replace(/\/+$/, '');

return $input.all()
  .map(({ json }) => {
    const rawLink = (json.link || '').trim();
    const link = normalizeLink(rawLink);

    let domain = '';
    try {
      domain = rawLink ? new URL(rawLink).hostname : '';
    } catch {}

    const pubDate =
      json.isoDate   ||
      json.pubDate   ||
      json.published ||
      json.created   ||
      json.date      ||
      '';

    const pub = new Date(pubDate);
    const age_minutes = isNaN(pub.getTime())
      ? null
      : Math.round((now - pub.getTime()) / 60000);

    return {
      json: {
        source:         'FinancialJuice',
        source_type:    'macro',
        title:          (json.title || '').trim(),
        link,
        domain,
        contentSnippet: stripHtml(
          json.contentSnippet || json.content || json.summary || ''
        ),
        pubDate,
        age_minutes,
      },
    };
  })
  // v4: Parse RSS 완전 동일 기준 (pubDate 없는 항목 제거)
  .filter(item =>
    item.json.title        &&
    item.json.link         &&
    item.json.pubDate      &&
    item.json.age_minutes !== null &&
    item.json.age_minutes <= 1440  &&
    item.json.age_minutes >= -60
  );
